//https://iquilezles.org/articles/distfunctions
float sdBox( vec3 p, vec3 b){
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

float sdf_test(vec3 p){
    vec3 d=vec3(0.6,0.6,2.0);
    return min(min(sdBox(p,d),sdBox(p,d.xzy)),sdBox(p,d.zxy));
}

float bevel_sdf(in vec3 p,in float b){
    vec3 k=vec3(1.0,0.0,-1.0)*b;
    float x1=sdf_test(p+k.xyy);
    float x2=sdf_test(p+k.zyy);
    float y1=sdf_test(p+k.yxy);
    float y2=sdf_test(p+k.yzy);
    float z1=sdf_test(p+k.yyx);
    float z2=sdf_test(p+k.yyz);
    return min(min(max((x1+x2)/2.0,(y1+y2)/2.0),max((y1+y2)/2.0,(z1+z2)/2.0)),max((z1+z2)/2.0,(x1+x2)/2.0));
}

//Rotation
vec2 rot(vec2 p,float f){
    float s=sin(f);float c=cos(f);
    return p*mat2(c,-s,s,c);
}

//Test Object
float sdf_a(vec3 p){

    //Rotate the object
    p.yz=rot(p.yz,sin(iTime*0.5)*2.0);
    p.xz=rot(p.xz,sin(iTime*0.2)*0.5);
    p.xy=rot(p.xy,sin(iTime*0.03)*2.0);

    float b=bevel_sdf(p,sin(iTime)*0.2+0.2);

    return b;
}

//Object Color
vec3 tex3d_a(vec3 p){
    return vec3(0.9,0.6,0.3);
}

//Floor
float sdf_b(vec3 p){
    return max(p.y+2.0,length(p)-8.0);
}

//Floor color
vec3 tex3d_b(vec3 p){
    p*=2.0;
	vec2 w=max(abs(dFdx(p.xz)),abs(dFdy(p.xz)))+1e-5;
	if (max(w.x,w.y)>0.5) {
		return vec3(mod(floor(p.x)+floor(p.z),2.0));
	}
	vec2 i=((1.-abs(2.*fract((p.xz+.5*w)/2.)-1.))-(1.-abs(2.*fract((p.xz-.5*w)/2.)-1.)))/w;
	return vec3(.5-.5*i.x*i.y);
}


//Combine the 2 SDFs
vec2 sdf(vec3 p) {
    float sdfa=sdf_a(p);
	float sdfb=sdf_b(p);
	if (sdfa<sdfb) {
	  return vec2(sdfa,0.0);
	} else {
	  return vec2(sdfb,1.0);
	}
}




//definition
vec3 raymarch(vec2 uv,vec3 camera,float cameraZoom,vec3 lookAt,
    float cameraDistance,vec3 sun,float ambOcclusion,float shadowIntensity,
    float ambLightIntensity,float lightPow,float lightSpecular,float reflection);

void mainImage( out vec4 fragColor, in vec2 fragCoord ){
    //setup uv
    vec2 uv=fragCoord/iResolution.xy-0.5;
    uv.x*=iResolution.x/iResolution.y;

    //rendering parameters
    vec3 camera=vec3(sin(sin(iTime*0.3)*0.5+0.5)*4.0,2.0,cos(cos(iTime*0.2)*0.5+0.5)*4.0);
    float cameraZoom=1.5;
    vec3 lookAt=vec3(0.0,0.0,0.0);
    float cameraDistance=1.1;
    vec3 sun=vec3(0.0,2.0,2.5);
    float ambOcclusion=1.0;
    float shadowIntensity=1.0;
    float ambLightIntensity=0.25;
    float lightPow=128.0;
    float lightSpecular=0.7;
    float reflection=0.2;
    vec3 col = raymarch(uv,camera,cameraZoom,lookAt,cameraDistance,sun,
        ambOcclusion,shadowIntensity,ambLightIntensity,lightPow,lightSpecular,reflection);

    fragColor = vec4(pow(col,vec3(1.0/2.2)),1.0);
}


//************************* Rendering framework ****************************************

vec3 normal(vec3 p){  
  const vec2 e=vec2(0.001,-0.001);
  float x=sdf(p+e.xyy).x;
  float y=sdf(p+e.yxy).x;
  float z=sdf(p+e.yyx).x;
  return normalize(vec3(x-y-z,-x+y-z,-x-y+z)+sdf(p+e.xxx).x);
}

void march(inout float d,out vec3 p,out vec2 dS,in vec3 ro,in vec3 rd){
    for (int i=0; i < 100; i++) {
    	p = ro + rd*d;
        dS = sdf(p);
        d += dS.x;
        if (d > 20.0 || abs(dS.x) < 0.0001) break;
    }
}

//from https://www.shadertoy.com/view/lsKcDD
float calcAO( in vec3 pos, in vec3 nor ){
	float occ = 0.0;
    float sca = 1.0;
    for( int i=0; i<5; i++ ){
        float h = 0.001 + 0.25*float(i)/4.0;
        float d = sdf( pos + h*nor ).x;
        occ += (h-d)*sca;
        sca *= 0.98;
    }
    return clamp( 1.0 - 1.6*occ, 0.0, 1.0 );    
}

//from https://www.shadertoy.com/view/lsKcDD
float calcSoftshadow( in vec3 ro, in vec3 rd, in float mint, in float tmax){
	float res = 1.0;
    float t = mint;
    float ph = 1e10; // big, such that y = 0 on the first iteration
    for( int i=0; i<32; i++ ){
		float h = sdf( ro + rd*t ).x;
        res = min( res, 10.0*h/t );
        t += h;
        if( res<0.0001 || t>tmax ) break;  
    }
    return clamp( res, 0.0, 1.0 );
}

vec3 hdri(vec3 p,float v) {
	return pow(texture(iChannel0, p).xyz, vec3(2.2))
    + pow(texture(iChannel0, p).xxx, vec3(16.0)) * v;
}

vec3 raymarch(
        vec2 uv,
        vec3 camera,
        float cameraZoom,
        vec3 lookAt,
        float cameraDistance,
        vec3 sun,
        float ambOcclusion,
        float shadowIntensity,
        float ambLightIntensity,
        float lightPow,
        float lightSpecular,
        float reflection) {
	vec3 cam=camera*cameraZoom;
	vec3 ray=normalize(lookAt-cam);
	vec3 cX=normalize(cross(vec3(0.0,1.0,0.0),ray));
	vec3 cY=normalize(cross(ray,cX));
	vec3 rd = normalize(ray*cameraDistance+cX*uv.x+cY*uv.y);
	vec3 ro = cam;

	float d=0.;
	vec3 p=vec3(0.);
	vec2 dS=vec2(0.);
	march(d,p,dS,ro,rd);

    vec3 color=vec3(0.);
	vec3 objColor=(dS.y<0.5)?tex3d_a(p):tex3d_b(p);
	vec3 light=normalize(sun);
	if (d<20.0) {
	    vec3 n=normal(p);
		float l=clamp(dot(-light,-n),0.,1.0);
		vec3 ref=normalize(reflect(rd,-n));
		float r=clamp(dot(ref,light),0.,1.0);
		float cAO=mix(1.0,calcAO(p,n),ambOcclusion);
		float shadow=mix(1.0,calcSoftshadow(p,light,0.05,5.),shadowIntensity);
		color=min(
            vec3(max(shadow,ambLightIntensity)),
            max(l,ambLightIntensity))*max(cAO,ambLightIntensity)*objColor+
                pow(r,lightPow)*lightSpecular;
		//reflection
        d=0.01;
		march(d,p,dS,p,ref);
		vec3 objColorRef=vec3(0.);
		if (d<20.0) {
			objColorRef=(dS.y<0.5)?tex3d_a(p):tex3d_b(p);
			n=normal(p);
			l=clamp(dot(-light,-n),0.,1.);
			objColorRef=max(l,ambLightIntensity)*objColorRef;
		} else {
			objColorRef=hdri(ref.zyx,1.0);
		}
		color=mix(color,objColorRef,reflection);
	} else {
		color=hdri(rd.zyx,0.0);
	}
	return color;
}
